from __future__ import annotations

import json
import logging
import time
from typing import Any, Callable
from urllib.parse import urlparse

import httpx

_log = logging.getLogger("transub_engine.mt.external")

ProgressCb = Callable[[dict[str, Any]], None]
CancelCheck = Callable[[], None]

DEFAULT_TIMEOUT_SEC = 120.0
DEFAULT_BATCH_SIZE = 32
API_VERSION = 1
# Transient adapter failures worth one more POST (timeout / gateway).
# 429/busy is handled separately with a longer wait budget.
TRANSIENT_HTTP_STATUSES = frozenset({502, 503, 504})
MAX_BATCH_ATTEMPTS = 3
# Poll while adapter is still working on a prior (timed-out) request.
BUSY_POLL_INITIAL_SEC = 2.0
BUSY_POLL_MAX_SEC = 15.0
BRIEF_SAMPLE_MAX = 160


class MtExternalError(RuntimeError):
    """External MT HTTP failure with a stable error code."""

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


def normalize_mt_external(cfg: Any) -> dict[str, Any]:
    """Normalize job ``mtExternal`` into a validated config dict."""
    if cfg is None:
        raise MtExternalError("MT_EXTERNAL_CONFIG", "mtExternal is required when mtBackend=external")
    if not isinstance(cfg, dict):
        raise MtExternalError("MT_EXTERNAL_CONFIG", "mtExternal must be an object")
    url = str(cfg.get("url") or "").strip()
    if not url:
        raise MtExternalError("MT_EXTERNAL_CONFIG", "mtExternal.url is required")
    parsed = urlparse(url)
    if parsed.scheme not in ("http", "https") or not parsed.netloc:
        raise MtExternalError("MT_EXTERNAL_CONFIG", f"mtExternal.url is invalid: {url}")

    timeout_raw = cfg.get("timeoutSec", cfg.get("timeout_sec", DEFAULT_TIMEOUT_SEC))
    try:
        timeout_sec = float(timeout_raw)
    except (TypeError, ValueError) as err:
        raise MtExternalError("MT_EXTERNAL_CONFIG", "mtExternal.timeoutSec must be a number") from err
    if timeout_sec <= 0:
        raise MtExternalError("MT_EXTERNAL_CONFIG", "mtExternal.timeoutSec must be > 0")

    batch_raw = cfg.get("batchSize", cfg.get("batch_size", DEFAULT_BATCH_SIZE))
    try:
        batch_size = int(batch_raw)
    except (TypeError, ValueError) as err:
        raise MtExternalError("MT_EXTERNAL_CONFIG", "mtExternal.batchSize must be an integer") from err
    if batch_size < 1:
        raise MtExternalError("MT_EXTERNAL_CONFIG", "mtExternal.batchSize must be >= 1")

    headers_raw = cfg.get("headers") or {}
    if not isinstance(headers_raw, dict):
        raise MtExternalError("MT_EXTERNAL_CONFIG", "mtExternal.headers must be an object")
    headers = {str(k): str(v) for k, v in headers_raw.items()}

    return {
        "url": url,
        "timeoutSec": timeout_sec,
        "batchSize": batch_size,
        "headers": headers,
    }


def _align_batch_response(
    batch: list[dict[str, Any]],
    payload: Any,
) -> list[str]:
    if not isinstance(payload, dict):
        raise MtExternalError("MT_EXTERNAL_RESPONSE", "response body must be a JSON object")
    cues = payload.get("cues")
    if not isinstance(cues, list):
        raise MtExternalError("MT_EXTERNAL_RESPONSE", "response.cues must be an array")
    if len(cues) != len(batch):
        raise MtExternalError(
            "MT_EXTERNAL_RESPONSE",
            f"response.cues length {len(cues)} != request batch {len(batch)}",
        )

    by_id: dict[int, str] = {}
    ordered: list[str | None] = [None] * len(batch)
    for i, item in enumerate(cues):
        if not isinstance(item, dict):
            raise MtExternalError("MT_EXTERNAL_RESPONSE", f"response.cues[{i}] must be an object")
        text = str(item.get("text") or "")
        if "id" in item and item.get("id") is not None:
            try:
                cid = int(item["id"])
            except (TypeError, ValueError) as err:
                raise MtExternalError(
                    "MT_EXTERNAL_RESPONSE", f"response.cues[{i}].id must be an integer"
                ) from err
            by_id[cid] = text
        else:
            ordered[i] = text

    out: list[str] = []
    for i, cue in enumerate(batch):
        cid = int(cue["id"])
        if cid in by_id:
            out.append(by_id[cid])
        elif ordered[i] is not None:
            out.append(str(ordered[i]))
        else:
            raise MtExternalError(
                "MT_EXTERNAL_RESPONSE",
                f"missing translated text for cue id={cid}",
            )
    return out


def _parse_error_body(resp: httpx.Response) -> tuple[str, str]:
    detail = (resp.text or "")[:300]
    code_hint = ""
    try:
        data = resp.json()
        if isinstance(data, dict):
            code_hint = str(data.get("code") or "")
            err_msg = str(data.get("error") or data.get("message") or "").strip()
            if err_msg:
                detail = err_msg[:300]
    except Exception:
        pass
    return code_hint, detail


def _raise_for_http_status(resp: httpx.Response) -> None:
    code_hint, detail = _parse_error_body(resp)
    code_l = code_hint.lower().strip()
    reason = detail or resp.reason_phrase or ""

    # Body semantics beat status: legacy adapters used 502/499 + aborted for timeouts.
    if code_l == "timeout" or (code_l == "aborted" and "超时" in reason):
        raise MtExternalError(
            "MT_EXTERNAL_TIMEOUT",
            f"external MT HTTP {resp.status_code}: {reason}",
        )
    if resp.status_code == 504:
        raise MtExternalError(
            "MT_EXTERNAL_TIMEOUT",
            f"external MT HTTP {resp.status_code}: {reason}",
        )

    # Job / adapter cancel (do not retry).
    if resp.status_code == 499 or code_l in ("cancelled", "canceled"):
        raise MtExternalError("MT_EXTERNAL_CANCELLED", f"external MT cancelled: {reason}")
    if code_l == "aborted" and "已取消" in reason:
        raise MtExternalError("MT_EXTERNAL_CANCELLED", f"external MT cancelled: {reason}")

    # Adapter still processing a prior request (timeout-retry race). Wait & retry.
    if resp.status_code == 429 or code_l == "busy" or "adapter busy" in reason.lower():
        raise MtExternalError(
            "MT_EXTERNAL_BUSY",
            f"external MT HTTP {resp.status_code}: {reason or 'adapter busy'}",
        )

    raise MtExternalError(
        "MT_EXTERNAL_HTTP",
        f"external MT HTTP {resp.status_code}: {reason}",
    )


def brief_sample_limit(cue_count: int) -> int:
    n = max(0, int(cue_count or 0))
    if n <= 60:
        return n
    if n <= 160:
        return 80
    if n <= 360:
        return 120
    return BRIEF_SAMPLE_MAX


def sample_brief_cues(
    cues: list[dict[str, Any]],
    max_items: int | None = None,
) -> list[dict[str, Any]]:
    """Head/mid/tail sample of full-film cues for adapter-side film brief."""
    n = len(cues)
    if n <= 0:
        return []
    limit = int(max_items) if max_items and max_items > 0 else brief_sample_limit(n)
    limit = max(1, min(BRIEF_SAMPLE_MAX, limit))
    if n <= limit:
        indexes = list(range(n))
    else:
        seen: set[int] = set()
        order: list[int] = []

        def push(i: int) -> None:
            if i < 0 or i >= n or i in seen:
                return
            seen.add(i)
            order.append(i)

        head = min(24, max(8, limit * 22 // 100))
        tail = head
        for i in range(head):
            push(i)
        for i in range(max(0, n - tail), n):
            push(i)
        mid_budget = max(1, limit - len(order))
        for i in range(mid_budget):
            idx = int((i + 0.5) * n / mid_budget)
            push(min(n - 1, idx))
        indexes = sorted(order)[:limit]

    out: list[dict[str, Any]] = []
    for i in indexes:
        c = cues[i]
        out.append(
            {
                "id": i,
                "start": c.get("start"),
                "end": c.get("end"),
                "text": str(c.get("text") or ""),
            }
        )
    return out


def _post_json(
    *,
    client: httpx.Client,
    url: str,
    headers: dict[str, str],
    body: dict[str, Any],
) -> Any:
    try:
        resp = client.post(url, headers=headers, content=json.dumps(body, ensure_ascii=False))
    except httpx.TimeoutException as err:
        raise MtExternalError("MT_EXTERNAL_TIMEOUT", f"external MT timed out: {err}") from err
    except httpx.RequestError as err:
        raise MtExternalError("MT_EXTERNAL_HTTP", f"external MT request failed: {err}") from err

    if resp.status_code < 200 or resp.status_code >= 300:
        _raise_for_http_status(resp)

    try:
        return resp.json()
    except Exception as err:
        raise MtExternalError("MT_EXTERNAL_RESPONSE", "response is not valid JSON") from err


def _post_batch_once(
    *,
    client: httpx.Client,
    url: str,
    headers: dict[str, str],
    job_id: str | None,
    language: str,
    target_language: str,
    batch: list[dict[str, Any]],
    brief_cues: list[dict[str, Any]] | None = None,
    brief_cue_total: int = 0,
) -> list[str]:
    body: dict[str, Any] = {
        "apiVersion": API_VERSION,
        "jobId": job_id or "",
        "language": language,
        "targetLanguage": target_language,
        "cues": batch,
    }
    if brief_cues:
        body["briefCues"] = brief_cues
        body["briefCueTotal"] = int(brief_cue_total or len(brief_cues))
    payload = _post_json(client=client, url=url, headers=headers, body=body)
    return _align_batch_response(batch, payload)


def _post_polish_finalize(
    *,
    client: httpx.Client,
    url: str,
    headers: dict[str, str],
    job_id: str | None,
    language: str,
    target_language: str,
    source_cues: list[dict[str, Any]],
    translated: list[dict[str, Any]],
    cancel_check: CancelCheck | None = None,
) -> list[str]:
    """
    After all sentence batches: one whole-film plot-polish pass (adapter may no-op).
    Request cues are source text; translatedCues carry current ZH.
    """
    if cancel_check:
        cancel_check()
    batch = [
        {
            "id": i,
            "start": c.get("start"),
            "end": c.get("end"),
            "text": str(c.get("text") or ""),
        }
        for i, c in enumerate(source_cues)
    ]
    translated_cues = [
        {
            "id": i,
            "text": str((translated[i] if i < len(translated) else {}).get("text") or ""),
        }
        for i in range(len(source_cues))
    ]
    body: dict[str, Any] = {
        "apiVersion": API_VERSION,
        "jobId": job_id or "",
        "language": language,
        "targetLanguage": target_language,
        "phase": "polish",
        "cues": batch,
        "translatedCues": translated_cues,
        "briefCueTotal": len(source_cues),
    }
    payload = _post_json(client=client, url=url, headers=headers, body=body)
    return _align_batch_response(batch, payload)


def _is_busy_error(err: MtExternalError) -> bool:
    if err.code == "MT_EXTERNAL_BUSY":
        return True
    return err.code == "MT_EXTERNAL_HTTP" and "HTTP 429:" in err.message


def _post_batch(
    *,
    client: httpx.Client,
    url: str,
    headers: dict[str, str],
    job_id: str | None,
    language: str,
    target_language: str,
    batch: list[dict[str, Any]],
    cancel_check: CancelCheck | None = None,
    timeout_sec: float = DEFAULT_TIMEOUT_SEC,
    brief_cues: list[dict[str, Any]] | None = None,
    brief_cue_total: int = 0,
) -> list[str]:
    last_err: MtExternalError | None = None
    hard_attempts = 0
    busy_sleep = BUSY_POLL_INITIAL_SEC
    # Allow waiting roughly one full batch timeout for an in-flight adapter job.
    deadline = time.monotonic() + max(float(timeout_sec), 30.0)

    while True:
        if cancel_check:
            cancel_check()
        try:
            return _post_batch_once(
                client=client,
                url=url,
                headers=headers,
                job_id=job_id,
                language=language,
                target_language=target_language,
                batch=batch,
                brief_cues=brief_cues,
                brief_cue_total=brief_cue_total,
            )
        except MtExternalError as err:
            last_err = err
            if err.code == "MT_EXTERNAL_CANCELLED":
                raise

            if _is_busy_error(err):
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise
                time.sleep(min(busy_sleep, BUSY_POLL_MAX_SEC, max(0.5, remaining)))
                busy_sleep = min(busy_sleep * 1.5, BUSY_POLL_MAX_SEC)
                continue

            hard_attempts += 1
            transient = err.code == "MT_EXTERNAL_TIMEOUT" or (
                err.code == "MT_EXTERNAL_HTTP"
                and any(f"HTTP {s}:" in err.message for s in TRANSIENT_HTTP_STATUSES)
            )
            if not transient or hard_attempts >= MAX_BATCH_ATTEMPTS:
                raise
            time.sleep(min(1.5 * hard_attempts, 4.0))
    assert last_err is not None
    raise last_err


def external_translate_cues(
    cues: list[dict[str, Any]],
    *,
    mt_external: dict[str, Any] | None,
    language: str = "",
    target_language: str = "zh",
    job_id: str | None = None,
    on_progress: ProgressCb | None = None,
    cancel_check: CancelCheck | None = None,
    http_client: httpx.Client | None = None,
) -> list[dict[str, Any]]:
    """
    Translate cues via an external HTTP adapter (LLM lives outside the engine).
    """
    cfg = normalize_mt_external(mt_external)
    url = cfg["url"]
    timeout_sec = float(cfg["timeoutSec"])
    batch_size = int(cfg["batchSize"])
    headers = {"Content-Type": "application/json", **dict(cfg["headers"])}
    host = urlparse(url).netloc or url

    total = max(len(cues), 1)
    out: list[dict[str, Any]] = [
        {"start": c.get("start"), "end": c.get("end"), "text": ""} for c in cues
    ]

    _log.info(
        "external MT start host=%s cues=%s batch_size=%s timeout=%ss job_id=%s",
        host,
        len(cues),
        batch_size,
        int(timeout_sec),
        job_id or "-",
    )

    if on_progress:
        on_progress(
            {
                "stage": "translate",
                "percent": 1,
                "detail": f"外部翻译 · {host}",
            }
        )

    if not cues:
        if on_progress:
            on_progress({"stage": "translate", "percent": 100, "detail": "0 条"})
        return out

    brief_cues = sample_brief_cues(cues)
    brief_cue_total = len(cues)

    def _check() -> None:
        if cancel_check:
            cancel_check()

    own_client = http_client is None
    client = http_client or httpx.Client(timeout=timeout_sec)
    try:
        done = 0
        for start in range(0, len(cues), batch_size):
            _check()
            # Emit at batch *start* so the UI advances before a long LLM wait.
            if on_progress:
                on_progress(
                    {
                        "stage": "translate",
                        "percent": int(100.0 * start / total),
                        "detail": f"翻译 {start}/{total}",
                    }
                )
            chunk = cues[start : start + batch_size]
            batch = [
                {
                    "id": start + i,
                    "start": c.get("start"),
                    "end": c.get("end"),
                    "text": str(c.get("text") or ""),
                }
                for i, c in enumerate(chunk)
            ]
            texts = _post_batch(
                client=client,
                url=url,
                headers=headers,
                job_id=job_id,
                language=language,
                target_language=target_language,
                batch=batch,
                cancel_check=cancel_check,
                timeout_sec=timeout_sec,
                brief_cues=brief_cues,
                brief_cue_total=brief_cue_total,
            )
            for i, text in enumerate(texts):
                out[start + i]["text"] = text
            done = start + len(chunk)
            if on_progress:
                on_progress(
                    {
                        "stage": "translate",
                        "percent": int(100.0 * done / total),
                        "detail": f"翻译 {done}/{total}",
                    }
                )

        # External LLM may leave short JA / moan cues blank; fill from whole-cue maps.
        try:
            from .ja_polish import fill_blank_zh_cues

            out = fill_blank_zh_cues(cues, out)
        except Exception:
            _log.exception("external MT blank-fill skipped")

        # Whole-film plot polish once (smart adapter); sakura / disabled adapters echo ZH.
        # Failures must not discard completed sentence MT.
        try:
            if on_progress:
                on_progress(
                    {
                        "stage": "translate",
                        "percent": 96,
                        "detail": "剧情贴合润色…",
                    }
                )
            polished_texts = _post_polish_finalize(
                client=client,
                url=url,
                headers=headers,
                job_id=job_id,
                language=language,
                target_language=target_language,
                source_cues=cues,
                translated=out,
                cancel_check=cancel_check,
            )
            for i, text in enumerate(polished_texts):
                if i < len(out):
                    out[i]["text"] = text
        except MtExternalError as err:
            _log.warning("external MT polish skipped: %s", err)
        except Exception:
            _log.exception("external MT polish skipped")
    finally:
        if own_client:
            client.close()

    _log.info(
        "external MT done host=%s cues=%s job_id=%s",
        host,
        len(out),
        job_id or "-",
    )
    if on_progress:
        on_progress(
            {
                "stage": "translate",
                "percent": 100,
                "detail": f"{len(out)} 条",
            }
        )
    return out
